 output.mkdir(parents=True,exist_ok=False);n=json.loads((evidence/'native-final/manifest.json').read_text());r=json.loads((evidence/'native-final-repeat/manifest.json').read_text());m=json.loads((evidence/'metal-final/manifest.json').read_text());assert n['status']==r['status']=='reference_complete'and m['status']=='pass';assert n['full_constructors']==r['full_constructors']==93;assert n['constructor']['factory']=='0x40dc00'and n['constructor']['actual_vtable']=='0x5a370c';assert m['scenario']['native_domain']and m['scenario']['frames']==60 and m['pixel_summary']['distinct_frames']==1;assert [(c['tick'],c.get('rgb565_sha256'))for c in n['cases']]==[(c['tick'],c.get('rgb565_sha256'))for c in r['cases']]
 ticks=(2,6,16,30,46,60);whole=Image.new('RGB',(1280,6*505));detail=Image.new('RGB',(1120,6*485));w=ImageDraw.Draw(whole);d=ImageDraw.Draw(detail);cases=[]
